      "tipo": "norma",
      "achados": [
        {
          "proposicao": "Nas medições de gás natural com placas de orifício, turbinas e medidores ultrassônicos, o trecho remete a documentos técnicos específicos para requisitos aplicáveis a cada tecnologia.",
          "trechos": [
            "Ea6d35581a3186b04:0:699",
            "Ea6d35581a3186b04:699:1398"
