          ]
        },
        {
          "proposicao": "As variações de composição do gás registradas em análises periódicas devem ser compensadas imediatamente após cada nova análise nas medições subsequentes.",
          "trechos": [
            "Ea6d35581a3186b04:1398:2088",
            "Ea6d35581a3186b04:2088:2294"
          ],
          "condicoes": [
            "quando houver análises periódicas de composição previstas no regulamento",
            "para medições subsequentes após cada nova análise"
          ],
          "limites": [
            "o trecho não informa periodicidade das análises nem o método analítico",
            "não detalha como a compensação deve ser implementada"
          ]
        }
      ]
    },
    {
