      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Em sistemas de transferência de custódia, pressão estática na parede do duto e temperatura do escoamento na estação de medição são apresentadas como medições que devem estar sempre presentes.",
          "trechos": [
            "E3f0f284fd4fee124:0:696"
          ],
          "condicoes": [
            "no contexto descrito de sistemas de medição de transferência de custódia"
          ],
          "limites": [
